private val RP=NumberFormat.getCurrencyInstance(Locale("id","ID")).apply{maximumFractionDigits=0}
private fun money(v:Long)=RP.format(v)
private fun JsonObject.s(vararg k:String)=k.firstNotNullOfOrNull{string(it)?.takeIf(String::isNotBlank)}?:"-"
private fun JsonObject.n(vararg k:String)=k.firstNotNullOfOrNull{long(it)}?:0L
private fun JsonObject.a(k:String)=array(k)?.filterIsInstance<JsonObject>()?:emptyList()

class NativeMainActivity:ComponentActivity(){override fun onCreate(b:Bundle?){super.onCreate(b);val session=SessionManager(applicationContext);val repo=Repository(ApiClient(session).api);val api=FeatureApiClient().api;setContent{val vm:AppViewModel=viewModel(factory=NF{AppViewModel(session,repo)});MaterialTheme{NativeApp(vm,repo,api,session)}}}}
@Composable private fun NativeApp(vm:AppViewModel,repo:Repository,api:FeatureApiService,session:SessionManager){val st by vm.state.collectAsState();when{st.loading->Box(Modifier.fillMaxSize(),contentAlignment=Alignment.Center){CircularProgressIndicator()};st.user==null->LoginNative(st.error,vm::login);else->HomeNative(st.user!!,vm::logout,repo,api,session)}}
@Composable private fun LoginNative(error:String?,login:(String,String)->Unit){var u by remember{mutableStateOf("demo")};var p by remember{mutableStateOf("demodemo")};Column(Modifier.fillMaxSize().padding(24.dp),verticalArrangement=Arrangement.Center){Text("IRKOP CELL",style=MaterialTheme.typography.headlineLarge);OutlinedTextField(u,{u=it},label={Text("Username")},modifier=Modifier.fillMaxWidth());OutlinedTextField(p,{p=it},label={Text("Password")},modifier=Modifier.fillMaxWidth());Button({login(u.trim(),p)},Modifier.fillMaxWidth()){Text("LOGIN")};error?.let{Text(it,color=MaterialTheme.colorScheme.error)}}}
@Composable private fun HomeNative(user:UserSession,logout:()->Unit,repo:Repository,api:FeatureApiService,session:SessionManager){var page by remember{mutableStateOf("dashboard")};val auth="Bearer ${session.token.orEmpty()}";val pages=buildList{if(AuthPolicy.canAccess(user,"dashboard"))add("dashboard" to "Dashboard");if(AuthPolicy.canAccess(user,"transaksi"))add("transaksi" to "Transaksi");if(AuthPolicy.canAccess(user,"kasir"))add("kasir" to "Kasir");if(AuthPolicy.canAccess(user,"laporan"))add("laporan" to "Laporan");add("produk" to "Produk");add("pelanggan" to "Pelanggan");add("kasbon" to "Kasbon");add("pengeluaran" to "Pengeluaran");add("service" to "Service HP");if(AuthPolicy.canAccess(user,"gaji_karyawan"))add("gaji" to "Gaji");add("akun" to "Akun Uang");if(AuthPolicy.canAccess(user,"pengaturan"))add("settings" to "Pengaturan")};Scaffold(topBar={TopAppBar({Text("IRKOP CELL · ${user.nama.ifBlank{user.username}}")},actions={TextButton(logout){Text("Logout")}})}){pad->Column(Modifier.fillMaxSize().padding(pad)){LazyColumn(Modifier.fillMaxWidth().heightIn(max=90.dp),contentPadding=PaddingValues(6.dp),horizontalArrangement=Arrangement.spacedBy(4.dp)){items(pages){(k,l)->FilterChip(page==k,{page=k},label={Text(l)})}};when(page){"dashboard"->DashboardN(repo);"transaksi"->TransaksiN(repo);"kasir"->KasirN(repo,api,auth);"laporan"->LaporanN(repo,api,auth);"produk"->ProdukN(api,auth);"pelanggan"->PelangganN(api,auth);"kasbon"->KasbonN(api,auth);"pengeluaran"->PengeluaranN(api,auth);"service"->ServiceN(api,auth);"gaji"->GajiN(api,auth);"akun"->AkunN(api,auth);"settings"->PengaturanN(api,auth)}}}}

@Composable private fun DashboardN(repo:Repository){var root by remember{mutableStateOf<JsonObject?>(null)};var err by remember{mutableStateOf<String?>(null)};val scope=rememberCoroutineScope();fun load(){scope.launch{runCatching{val t=repo.transaksi(tanggal=LocalDate.now().toString());val k=repo.kasirCurrent();val b=repo.kasbon();buildJsonObject{put("t",t);put("k",k);put("b",b)}}.onSuccess{root=it}.onFailure{err=ApiError.message(it)}}};LaunchedEffect(Unit){load()};val t=root?.obj("t");val k=root?.obj("k");val b=root?.obj("b");LazyColumn(Modifier.fillMaxSize().padding(12.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){item{Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Text("Dashboard",style=MaterialTheme.typography.headlineMedium);TextButton(load){Text("Refresh")}}};err?.let{item{Err(it)}};item{Row(Modifier.fillMaxWidth(),Arrangement.spacedBy(6.dp)){Stat("Omzet",money(t?.n("total_nilai","total_omzet","omzet")?:0),Modifier.weight(1f));Stat("Transaksi",(t?.n("total_items","jumlah_transaksi")?:t?.a("items")?.size?.toLong()?:0).toString(),Modifier.weight(1f))}};item{Row(Modifier.fillMaxWidth(),Arrangement.spacedBy(6.dp)){Stat("Kasbon aktif",b?.a("items")?.count{it.s("status").contains("belum",true)}?.toString()?:"0",Modifier.weight(1f));Stat("Kasir",k?.s("status")?:"-",Modifier.weight(1f))}};item{Text("Saldo per akun",style=MaterialTheme.typography.titleLarge)};items(k?.a("saldo")?:emptyList()){Info(it.s("nama_akun"),money(it.n("saldo_sistem","saldo")))};item{Text("Transaksi terbaru",style=MaterialTheme.typography.titleLarge)};items(t?.a("items")?.take(10)?:emptyList()){Info(it.s("id","kode"),"${money(it.n("total","nominal"))} · ${it.s("metode_bayar")}")}}}

@Composable private fun TransaksiN(repo:Repository){val scope=rememberCoroutineScope();var rows by remember{mutableStateOf(emptyList<JsonObject>())};var q by remember{mutableStateOf("")};var date by remember{mutableStateOf("")};var from by remember{mutableStateOf("")};var to by remember{mutableStateOf("")};var method by remember{mutableStateOf("")};var conf by remember{mutableStateOf("")};var detail by remember{mutableStateOf<JsonObject?>(null)};var create by remember{mutableStateOf(false)};var err by remember{mutableStateOf<String?>(null)};fun load(){scope.launch{runCatching{repo.transaksi(q.ifBlank{null},date.ifBlank{null},from.ifBlank{null},to.ifBlank{null},method.ifBlank{null},conf.ifBlank{null})}.onSuccess{rows=it.a("items")}.onFailure{err=ApiError.message(it)}}};LaunchedEffect(Unit){load()};Column(Modifier.fillMaxSize().padding(10.dp)){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Text("Transaksi",style=MaterialTheme.typography.headlineMedium);Button({create=true}){Text("BARU")}};OutlinedTextField(q,{q=it},label={Text("Search")},modifier=Modifier.fillMaxWidth());Row{OutlinedTextField(date,{date=it},label={Text("Tanggal")},Modifier.weight(1f));OutlinedTextField(from,{from=it},label={Text("Mulai")},Modifier.weight(1f));OutlinedTextField(to,{to=it},label={Text("Selesai")},Modifier.weight(1f))};Row{listOf("" to "Semua","tunai" to "Tunai","transfer" to "Transfer","bon" to "Bon","cash_tunai" to "Cash").forEach{(v,l)->FilterChip(method==v,{method=v},label={Text(l)})}};Row{listOf("" to "Semua","menunggu" to "Menunggu","otomatis" to "Otomatis","manual" to "Manual","tidak_perlu" to "Tidak perlu").forEach{(v,l)->FilterChip(conf==v,{conf=v},label={Text(l)})}};Button(load,Modifier.fillMaxWidth()){Text("FILTER")};err?.let{Err(it)};LazyColumn{items(rows){r->Card({scope.launch{runCatching{repo.transaksiDetail(r.s("id"))}.onSuccess{detail=it}.onFailure{err=ApiError.message(it)}}},Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text(r.s("id"));Text(money(r.n("total")));Text(r.s("metode_bayar"));Text(r.s("konfirmasi_pembayaran"))}}}}};if(create)TransactionForm(repo,{create=false;load()},{create=false});detail?.let{TransactionDetailN(repo,it,{detail=null;load()},{detail=null})}}

@Composable private fun TransactionForm(repo:Repository,done:()->Unit,cancel:()->Unit){val scope=rememberCoroutineScope();var products by remember{mutableStateOf(emptyList<JsonObject>())};var cart by remember{mutableStateOf(emptyList<Pair<JsonObject,Int>>())};var method by remember{mutableStateOf("tunai")};var customer by remember{mutableStateOf("")};var receiver by remember{mutableStateOf("")};var manual by remember{mutableStateOf(false)};var date by remember{mutableStateOf(LocalDate.now().toString())};var picker by remember{mutableStateOf(false)};var err by remember{mutableStateOf<String?>(null)};var busy by remember{mutableStateOf(false)};LaunchedEffect(Unit){runCatching{repo.produk()}.onSuccess{products=it.a("items")}.onFailure{err=ApiError.message(it)}};val total=cart.sumOf{it.first.n("harga")*it.second};AlertDialog(cancel,title={Text("Transaksi Baru")},text={LazyColumn(Modifier.heightIn(max=560.dp)){item{Text("Keranjang")};items(cart){(p,q)->Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Text("${p.s("nama")} × $q");Row{TextButton({cart=cart.mapNotNull{if(it.first.s("id")==p.s("id")){if(q>1)p to q-1 else null}else it}}){Text("−")};TextButton({cart=cart.map{if(it.first.s("id")==p.s("id"))p to q+1 else it}}){Text("+")}}}};item{Button({picker=true},Modifier.fillMaxWidth()){Text("Tambah produk")}};item{Info("Total",money(total))};item{OutlinedTextField(customer,{customer=it.filter(Char::isDigit)},label={Text("Pelanggan ID")},modifier=Modifier.fillMaxWidth())};item{Row{listOf("tunai","transfer","bon","cash_tunai").forEach{FilterChip(method==it,{method=it},label={Text(it)})}}};if(method=="transfer")item{OutlinedTextField(receiver,{receiver=it},label={Text("Akun penerima")},modifier=Modifier.fillMaxWidth())};item{Row(verticalAlignment=Alignment.CenterVertically){Checkbox(manual,{manual=it});Text("Manual entry / backdate")}};if(manual)item{OutlinedTextField(date,{date=it},label={Text("YYYY-MM-DD, max 30 hari")},modifier=Modifier.fillMaxWidth())};err?.let{item{Err(it)}}}},confirmButton={Button(cart.isNotEmpty()&&!busy,{if(method=="bon"&&customer.toLongOrNull()==null)err="Pelanggan wajib" else if(method=="transfer"&&receiver.isBlank())err="Akun penerima wajib" else{busy=true;scope.launch{runCatching{repo.createTransaksi(buildJsonObject{putJsonArray("items"){cart.forEach{(p,q)->add(buildJsonObject{put("produk_id",p["id"]!!);put("qty",q)})}};put("metode_bayar",method);customer.toLongOrNull()?.let{put("pelanggan_id",it)};if(receiver.isNotBlank())put("akun_penerima",receiver);put("manual_entry",manual);if(manual)put("tanggal_transaksi",date)})}.onSuccess{done()}.onFailure{err=ApiError.message(it)};busy=false}}}}){Text(if(busy)"Menyimpan…" else "Simpan")},dismissButton={TextButton(cancel){Text("Batal")}});if(picker)AlertDialog({picker=false},title={Text("Produk")},text={LazyColumn{items(products){p->TextButton({val e=cart.firstOrNull{it.first.s("id")==p.s("id")};cart=if(e==null)cart+(p to 1)else cart.map{if(it.first.s("id")==p.s("id"))p to it.second+1 else it};picker=false},Modifier.fillMaxWidth()){Text("${p.s("nama")} · ${money(p.n("harga"))}")}}}},confirmButton={TextButton({picker=false}){Text("Tutup")}})}}

@Composable private fun TransactionDetailN(repo:Repository,d:JsonObject,done:()->Unit,cancel:()->Unit){val scope=rememberCoroutineScope();var confirm by remember{mutableStateOf(d.s("konfirmasi_pembayaran").let{if(it=="-")"menunggu" else it})};var reverse by remember{mutableStateOf(false)};var reason by remember{mutableStateOf("")};var msg by remember{mutableStateOf<String?>(null)};AlertDialog(cancel,title={Text("Detail ${d.s("id")}")},text={LazyColumn{item{Text("Tanggal: ${d.s("tanggal_transaksi")}")};item{Text("Total: ${money(d.n("total"))}")};item{Row{listOf("menunggu","otomatis","manual","tidak_perlu").forEach{FilterChip(confirm==it,{confirm=it},label={Text(it)})}}};item{Button({scope.launch{runCatching{repo.updateTransaksiKonfirmasi(d.s("id"),confirm)}.onSuccess{msg="Status tersimpan"}.onFailure{msg=ApiError.message(it)}}}){Text("Simpan konfirmasi")}};msg?.let{item{Text(it)}};if(reverse)item{OutlinedTextField(reason,{reason=it},label={Text("Alasan reversal")},modifier=Modifier.fillMaxWidth())};items(d.a("items")){Text("${it.s("nama_produk_snapshot","nama_produk")} × ${it.n("qty")}")}}},confirmButton={if(!reverse)TextButton({reverse=true}){Text("Hapus / Reversal") }else Button({scope.launch{runCatching{repo.deleteTransaksi(d.s("id"),reason.ifBlank{null})}.onSuccess{done()}.onFailure{msg=ApiError.message(it)}}}){Text("Konfirmasi reversal")}},dismissButton={TextButton({if(reverse)reverse=false else cancel()}){Text(if(reverse)"Batal" else "Tutup")}})}

@Composable private fun KasirN(repo:Repository,api:FeatureApiService,auth:String){val scope=rememberCoroutineScope();var data by remember{mutableStateOf<JsonObject?>(null)};var accounts by remember{mutableStateOf(emptyList<JsonObject>())};var reminder by remember{mutableStateOf<JsonObject?>(null)};var open by remember{mutableStateOf(false)};var close by remember{mutableStateOf(false)};var err by remember{mutableStateOf<String?>(null)};fun load(){scope.launch{runCatching{repo.kasirCurrent()}.onSuccess{data=it}.onFailure{err=ApiError.message(it)};runCatching{api.akun(auth)}.onSuccess{accounts=it.a("items")};runCatching{repo.reminderClosing()}.onSuccess{reminder=it}}};LaunchedEffect(Unit){load()};LazyColumn(Modifier.fillMaxSize().padding(12.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){item{Text("Kasir",style=MaterialTheme.typography.headlineMedium)};item{Info("Status",data?.s("status")?:"-")};items(data?.a("saldo")?:emptyList()){Info(it.s("nama_akun"),"Opening ${money(it.n("saldo_opening"))} · Sistem ${money(it.n("saldo_sistem"))} · Selisih dapat direkonsiliasi saat closing")};reminder?.takeIf{it.boolean("perlu_diingatkan")==true}?.let{item{Err("Sesi lama belum closing: ${it.a("sesi_buka_lampau").joinToString{r->r.s("tanggal")}}")}};item{Button({open=true},Modifier.fillMaxWidth()){Text("OPENING")}};item{Button({close=true},Modifier.fillMaxWidth()){Text("CLOSING / REKONSILIASI")}}};if(open)SessionDialog("Opening",accounts){v->scope.launch{runCatching{repo.opening(v)}.onSuccess{open=false;load()}.onFailure{err=ApiError.message(it)}}};if(close)SessionDialog("Closing",accounts){v->scope.launch{runCatching{repo.closing(v,null)}.onSuccess{close=false;load()}.onFailure{err=ApiError.message(it)}}}}
@Composable private fun SessionDialog(title:String,accounts:List<JsonObject>,save:(List<Pair<String,Long>>)->Unit){var v by remember{mutableStateOf(emptyMap<String,String>())};AlertDialog({},{Text(title)},{LazyColumn{items(accounts){a->val n=a.s("nama_akun");OutlinedTextField(v[n]?:"",{v=v+(n to it.filter(Char::isDigit))},label={Text(n)},modifier=Modifier.fillMaxWidth())}}},{Button({save(accounts.map{it.s("nama_akun") to (v[it.s("nama_akun")]?:"0").toLong())}){Text("Simpan")}},TextButton({}){Text("Batal")}})}

