@Composable private fun GajiN(api:FeatureApiService,auth:String){var rows by remember{mutableStateOf(emptyList<JsonObject>())};var users by remember{mutableStateOf(emptyList<JsonObject>())};var rate by remember{mutableStateOf(false)};var create by remember{mutableStateOf(false)};val scope=rememberCoroutineScope();fun load(){scope.launch{runCatching{api.gaji(auth)}.onSuccess{rows=it.a("items")};runCatching{api.users(auth)}.onSuccess{users=it.a("items").filter{u->u.s("role").equals("karyawan",true)}}}};LaunchedEffect(Unit){load()};Crud("Gaji",rows,"",{},load,{create=true},{},{}){"${it.s("tanggal")} · ${it.s("nama_karyawan")} · ${money(it.n("nominal"))}"};itemRate(users,{rate=true});if(create)SimpleForm("Gaji",null,{create=false},{v->scope.launch{runCatching{api.createGaji(auth,buildJsonObject{put("user_id",v[0].toLongOrNull()?:0);put("tanggal",v[1]);put("nominal",v[2].toLongOrNull()?:0);put("catatan",v[3])})}.onSuccess{create=false;load()}}});if(rate)SimpleForm("Rate Gaji",null,{rate=false},{v->scope.launch{runCatching{api.updateGajiRate(auth,buildJsonObject{put("user_id",v[0].toLongOrNull()?:0);put("tipe","flat");put("rate_flat",v[1].toLongOrNull()?:0)})}.onSuccess{rate=false;load()}}})}
