@Composable private fun PengaturanN(api:FeatureApiService,auth:String,user:UserSession){var data by remember{mutableStateOf<JsonObject?>(null)};var users by remember{mutableStateOf(emptyList<JsonObject>())};var logs by remember{mutableStateOf(emptyList<JsonObject>())};var name by remember{mutableStateOf("")};var theme by remember{mutableStateOf("classic")};var auto by remember{mutableStateOf(false)};var key by remember{mutableStateOf("")};var source by remember{mutableStateOf("")};var matcher by remember{mutableStateOf("")};val scope=rememberCoroutineScope();fun load(){scope.launch{runCatching{api.settings(auth)}.onSuccess{data=it;name=it.s("nama_website").let{v->if(v=="-")""else v};theme=it.s("default_theme");auto=it["notifhook"]?.jsonObject?.boolean("auto_input")==true;key=it["notifhook"]?.jsonObject?.s("api_key").orEmpty()};runCatching{api.users(auth)}.onSuccess{users=it.a("items")};runCatching{api.logs(auth)}.onSuccess{logs=it.a("items")}}};LaunchedEffect(Unit){load()};LazyColumn(Modifier.fillMaxSize().padding(12.dp),verticalArrangement=Arrangement.spacedBy(7.dp)){item{Text("Pengaturan",style=MaterialTheme.typography.headlineMedium)};item{OutlinedTextField(name,{name=it},label={Text("Website name")},modifier=Modifier.fillMaxWidth());Row{listOf("classic","paper","dark").forEach{FilterChip(theme==it,{theme=it},label={Text(it)})}};Row(verticalAlignment=Alignment.CenterVertically){Checkbox(auto,{auto=it});Text("NotifHook auto-confirm/input")};Button({scope.launch{runCatching{api.updateSettings(auth,buildJsonObject{put("nama_website",name);put("default_theme",theme);put("notifhook_auto_input",auto)})}.onSuccess{load()}}}){Text("SIMPAN")}};item{Button({scope.launch{runCatching{api.generateSettings(auth)}.onSuccess{key=it.s("api_key")}}}){Text("GENERATE API KEY")};if(key.isNotBlank())Text(key)};item{OutlinedTextField(source,{source=it},label={Text("NotifHook source")},modifier=Modifier.fillMaxWidth());OutlinedTextField(matcher,{matcher=it},label={Text("Package matcher")},modifier=Modifier.fillMaxWidth());Button({scope.launch{api.updateNotifhookSource(auth,buildJsonObject{put("source_name",source);put("matcher_type","package_name");put("matcher_value",matcher);put("enabled",true)})}}){Text("SIMPAN SOURCE")}};item{Text("User management / permission",style=MaterialTheme.typography.titleLarge)};items(users){Info(it.s("nama","username"),it.s("role"))};item{Text("Audit log",style=MaterialTheme.typography.titleLarge)};items(logs.take(30)){Info(it.s("aksi","action"),"${it.s("tabel","table")} · ${it.s("user","username")}")}}}

@Composable private fun Crud(title:String,rows:List<JsonObject>,q:String,onQ:(String)->Unit,refresh:()->Unit,new:()->Unit,edit:(JsonObject)->Unit,delete:(String)->Unit,line:(JsonObject)->String){Column(Modifier.fillMaxSize().padding(8.dp)){Row(Modifier.fillMaxWidth(),Arrangement.SpaceBetween){Text(title,style=MaterialTheme.typography.headlineMedium);Button(new){Text("BARU")}};if(q.isNotEmpty()||title=="Produk"||title=="Pelanggan"||title=="Pengeluaran")OutlinedTextField(q,onQ,label={Text("Search")},modifier=Modifier.fillMaxWidth());Button(refresh,Modifier.fillMaxWidth()){Text("Refresh")};LazyColumn(verticalArrangement=Arrangement.spacedBy(5.dp)){items(rows){r->Card(Modifier.fillMaxWidth()){Column(Modifier.padding(9.dp)){Text(line(r));if(title in setOf("Produk","Pelanggan","Pengeluaran","Kasbon")){Row{TextButton({edit(r)}){Text("Edit")};TextButton({delete(r.s("id"))}){Text("Hapus/Reversal")}}}}}}}}}}
@Composable private fun SimpleForm(title:String,old:JsonObject?,cancel:()->Unit,save:(List<String>)->Unit){val scope=rememberCoroutineScope();var v by remember{mutableStateOf(List(8){i->old?.let{when(title){"Produk"->listOf(it.s("kode"),it.s("nama"),it.s("harga"),it.s("harga_modal"),it.s("kategori_id"),it.s("stok"),it.s("stok_minimum"),it.s("satuan"))[i];"Pelanggan"->listOf(it.s("nama"),it.s("telepon"))[i];"Kasbon"->listOf(it.s("pelanggan_id"),it.s("nominal"),it.s("tanggal"),it.s("jatuh_tempo"),it.s("catatan"),it.s("status"))[i];"Pengeluaran"->listOf(it.s("deskripsi"),it.s("kategori"),it.s("nominal"),it.s("metode_bayar"),it.s("akun_sumber"),it.s("tanggal"))[i];"Service HP"->listOf(it.s("pelanggan_id"),it.s("nama_device"),it.s("deskripsi_kerusakan"),it.s("estimasi_biaya"),it.s("harga_modal"),it.s("tanggal_masuk"))[i];else->""}}?:""})};AlertDialog(cancel,title={Text(title)},text={LazyColumn{v.indices.forEach{i->item{OutlinedTextField(v[i],{x->v=v.toMutableList().also{it[i]=x}},label={Text(labelFor(title,i))},modifier=Modifier.fillMaxWidth())}}}},confirmButton={Button({save(v)}){Text("Simpan")}},dismissButton={TextButton(cancel){Text("Batal")}})}
private fun labelFor(t:String,i:Int)=when(t){"Produk"->listOf("Kode","Nama","Harga jual","Harga modal","Kategori ID","Stok","Stok minimum","Satuan")[i];"Pelanggan"->listOf("Nama","Telepon")[i];"Kasbon"->listOf("Pelanggan ID","Nominal","Tanggal","Jatuh tempo","Catatan","Status (lunas)",""," ")[i];"Pengeluaran"->listOf("Deskripsi","Kategori","Nominal","Metode tunai/transfer","Akun sumber","Tanggal",""," ")[i];"Service HP"->listOf("Pelanggan ID","Device","Keluhan","Estimasi biaya","Harga modal","Tanggal masuk",""," ")[i];"Gaji"->listOf("User karyawan","Tanggal","Nominal","Catatan","","","","")[i];"Rate Gaji"->listOf("User karyawan","Rate flat","","","","","","")[i];"Akun Uang"->listOf("Nama akun","Tipe","","","","","","")[i];else->"Field $i"}
private fun prodBody(v:List<String>)=buildJsonObject{put("kode",v[0]);put("nama",v[1]);put("harga",v[2].toLongOrNull()?:0);put("harga_modal",v[3].toLongOrNull()?:0);put("kategori_id",v[4].toLongOrNull()?:JsonNull);put("stok",v[5].toLongOrNull()?:0);put("stok_minimum",v[6].toLongOrNull()?:0);put("satuan",v[7].ifBlank{"pcs"})}
@Composable private fun Stat(t:String,v:String,m:Modifier)=Card(m){Column(Modifier.padding(10.dp)){Text(t);Text(v,style=MaterialTheme.typography.titleLarge)}}
@Composable private fun Info(t:String,v:String)=Card(Modifier.fillMaxWidth()){Column(Modifier.padding(10.dp)){Text(t,style=MaterialTheme.typography.labelMedium);Text(v)}}
@Composable private fun Err(v:String)=Card(Modifier.fillMaxWidth(),colors=CardDefaults.cardColors(containerColor=MaterialTheme.colorScheme.errorContainer)){Text(v,Modifier.padding(10.dp))}
@Composable private fun itemSpacer(){Spacer(Modifier.height(6.dp))}
private fun shareSimple(c:Context,title:String,text:String){c.startActivity(Intent.createChooser(Intent(Intent.ACTION_SEND).apply{type="text/plain";putExtra(Intent.EXTRA_TEXT,text)},title))}
private class NF<T:androidx.lifecycle.ViewModel>(private val f:()->T):androidx.lifecycle.ViewModelProvider.Factory{override fun<R:androidx.lifecycle.ViewModel>create(c:Class<R>):R{@Suppress("UNCHECKED_CAST")return f() as R}}
